			/**
			 *  가족특성구분코드 
			 * @param {any} psSeltVal
			 */
			function selectChBoxGrpEtc(psSeltVal){
			    
			    /* 2023-02-15 YOO.CHI.HOON 가족특성구분코드->코드선택에서 복수선택으로 변경요청(여가부 코드수정의견)*/ 
			//    if(ValueUtil.isNull(psSeltVal)) return;
			    
			    var chBoxEnableYn = '';
			    var chBoxGb     = app.lookup("cbg_FAM_CHAR_SE_CD_NM");
			    var chBoxgVals  = chBoxGb.values;
			    
			        if(chBoxgVals.indexOf('99') >= 0){
			            chBoxGb.putValue('');
			            chBoxEnableYn = 'value == "99"';           
			            chBoxGb.enabledItemExp = chBoxEnableYn;
			            
			            app.lookup("grp12").getLayout().setColumnVisible(1, true);
			            
			            if(msCrudType == "CREATE" || msCrudType == "UPDATE"){
			                app.lookup("ipb2").focus();
			            }            
			            
			            chBoxGb.putValue('99');
			        }else if(chBoxgVals.indexOf('99') == -1){
			            
			            chBoxEnableYn = 'value != "99" || value == "99"';           
			            chBoxGb.enabledItemExp = chBoxEnableYn;
			            
			            app.lookup("ipb2").value = "";
			            app.lookup("grp12").getLayout().setColumnVisible(1, false);
			        }
			    chBoxGb.redraw();
			}

			/**
			 * 개인식별등록 팝업을 오픈(개인식별번호)
			 * @param {any} psVal {read, save, update}
			 */
			function idntfcTrprPopUpOpen(psVal){
			    
			    /* 개인식별 정보*/
			    var vsIndvIdntfcNo   = app.lookup("dmDetail").getValue("INDV_IDNTFC_NO");   
			    var vsRrno           = app.lookup("dmDetail").getValue("RRNO");   
			    
			    var btnIndvIdntfcReg2 = app.lookup("btnIndvIdntfcReg2");    /* 개인식별버튼*/
			    
			    /* 주민번호 있는경우 개인식별팝업 X*/
			    if(vsRrno != '' && vsRrno != 'null' && vsRrno != null){
			//        console.log("1");
			        btnIndvIdntfcReg2.visible = false;        
			        return;
			    }
			    /* 개인식별번호 있는경우*/
			    if(vsIndvIdntfcNo != '' && vsIndvIdntfcNo != null){
			//        console.log("2");
			        btnIndvIdntfcReg2.visible = false;        
			        return;
			    }
			    var vsTrprNm      = app.lookup("dmDetail").getValue("TRPR_NM").toString();   
			    var vsTrprBrthYmd = app.lookup("dmDetail").getValue("TRPR_BRTH_YMD").toString();   
			    var vsSxdcSeCd    = app.lookup("dmDetail").getValue("SXDC_SE_CD").toString();   
			    
			    if(vsTrprNm.indexOf('미확인') >= 0 ||  vsTrprBrthYmd.indexOf('19000101') >= 0 || vsSxdcSeCd.indexOf('X') >= 0){
			//        console.log("3");
			        btnIndvIdntfcReg2.visible = false;        
			        return;
			    }
			    
			    /* 개인식별번호 없음*/
			//    console.log(vsIndvIdntfcNo);
			    if(vsIndvIdntfcNo == '' || vsIndvIdntfcNo == null){
			//        console.log("4");
			        btnIndvIdntfcReg2.visible = true;        
			    }
			    
			    if(psVal == 'save' || psVal == 'update'){
			        
			        /* 2023-01-12 YOO.CHI.HOON 여가부 요청사항 대상자등록 후 (개인식별팝업 오픈)*/
			        var voInitValue = {};
			        /* 상세dataMap*/
			        var dtlDataMap = app.lookup("dmDetail");
			        /* 중복dataMap*/
			        var chkCnt     = dtlDataMap.getValue("CHK_CNT");
			        var cnt = ValueUtil.fixNumber(chkCnt);
			        
			        if(cnt > 0){
			            if (ValueUtil.isNull(vsIndvIdntfcNo)) {
			                voInitValue = {
			                    "TRPR_NM"      : vsTrprNm,          // 대상자명
			                    "TRPR_BRTH_YMD": vsTrprBrthYmd,     // 대상자생년월일
			                    "SXDC_SE_CD"   : vsSxdcSeCd         // 성별
			                };
			            }
			            util.Msg.alert(app, "대상자명,생년월일,성별이 같은 대상자가 존재합니다.", null, function(e){
			                
			                var appid = "app/itgcm/bizcmmns/popup/idntfcTrprPop";
			                var headerTitle = "개인식별등록";
			                var width = 1260; //1560
			                var height = 700;
			                
			                util.Dialog.open(app, appid, headerTitle, width, height, function(e){
			            
			                var dialog = e.control;
			                var voReturnVal = dialog.returnValue;        
			            
			                if (!ValueUtil.isNull(voReturnVal)) {
			                    
			                    doDetail();
			                        }        
			                }, voInitValue, null, null);
			                
			            }, "개인식별");
			        }
			    }
			}



			/**
			 * 상세 데이터 저장
			 */
			function doSave() {
			    
			    // 프리폼 내 컬럼 유효성 체크
			    if (!util.validate(app, "grpTrprInfo")) return false; // 개인정보
			    //    if (!util.validate(app, "grpPrtcrSub")) return false; // 보호자정보
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            
			//            util.Msg.alert(app, "INF-M000", "입력하신 대상자가 저장 되었습니다.");
			            
			            // 저장 후 재조회를 위한 대상자정보번호(TR)를 반환받는다.
			            vsTrprInfoNo = app.lookup("subSave").getMetadata("TRPR_INFO_NO");
			            // 재조회용 dmDtlParam에 정보 저장
			            //util.DataMap.setValue(app, "dmSeqrch", "TRPR_INFO_NO", vsTrprInfoNo);
			            app.lookup("dmSearch").setValue("TRPR_INFO_NO", vsTrprInfoNo);
			            
			            var sType = '';
			            if( msCrudType == 'CREATE'){
			                sType = 'save';
			            }else if( msCrudType == 'UPDATE'){
			                sType = 'update';
			            }            
			            
			            // 재조회
			            doDetail(sType);
			            
			        } else {
			            util.Msg.alert(app, "INF-M000", "발굴대상자 정보가 저장 되지 않았습니다.", null, "발굴대상자 저장");
			        }
			    });
			}

			/**
			 * 상세 데이터 삭제
			 */
			function doDelete() {
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subDeleteTrpr", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            util.Msg.alert(app, "요청하신 대삭자가 삭제 되었습니다", "대상자정보 삭제");
			            if(app.getRootAppInstance().hasAppMethod("getMenuPath")){
			                    var voMenuInfo = util.Auth.getMenuInfo(app);
			                    var vsCallPage = voMenuInfo.get("URL_ADDR");
			                    vsCallPage = vsCallPage.replace(".clx", "");
			                    var mdiCn = app.getRootAppInstance().lookup("mdiCn");
			                    var vcFindItem = mdiCn.findItemWithAppID(vsCallPage);
			                    mdiCn.close(vcFindItem);
			            }               
			        } 
			    });
			}


