			/**
			 * 대상자 중복등록 체크
			 * @param {String} dataSetId    데이터셋 아이디
			 * @param {String} gridId       그리드 아이디
			 * @param {any} columnName      중복체크 컬럼이름
			 */
			function fn_trprDpcn(dataSetId, gridId, columnName) {
			    // 2022-09-26 YOO.CHI.HOON 사례공통정보 사례가족정보 UNIQUE 체크 (대상자 중복등록 X) 
			    var voDataSet = app.lookup(dataSetId);
			    var pnRowIndex = util.Grid.getIndex(app, gridId);
			    var vcColVal = util.Grid.getCellValue(app, gridId, columnName, pnRowIndex);
			    
			    if (vcColVal == null && vcColVal == "" && vcColVal.length < 0 && pnRowIndex < 0) {
			        var psTitle = "대상자정보";
			        var psMsgId = "대상자가 선택되지 않았습니다.\n대상자를 조회하여 선택 하시기 바랍니다.";
			        
			        util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			        return false;
			    } else {
			        var vcColVal2 = voDataSet.getColumnData(columnName);
			        
			        for (var i = 0; i < vcColVal2.length; i++) {
			            var dupChkCnt = 0;
			            for (var j = 0; j < vcColVal2.length; j++) {
			                
			                if (vcColVal2[i] == vcColVal2[j]) dupChkCnt++;
			            }
			            if (dupChkCnt > 1) {
			                break;
			            }
			        }
			        return dupChkCnt;
			    }
			}

