			/**
			 * @param {String} today  YYYYMMDD 오늘일자 문자 입력
			 * 만나이 구하기
			 */
			function ageChk_fn(today) {
			    
			    // 2022-10-27 YOO.CHI.HOON 만나이 구하기 (보호자생년월일 추가시 추가요청 , 생년월일 옆 만나이 기재 희망)
			    if (ValueUtil.isNull(today)) return false;
			    
			    var getLen = ValueUtil.getLength(today);
			    if (getLen != 8) return false;
			    
			    var chgNum = ValueUtil.fixNumber(today);
			    var boNum = ValueUtil.isNumber(chgNum);
			    if (boNum == false) return false;
			    
			    var iToday = ValueUtil.fixNumber(today); /* 입력한 오늘일자*/
			    var year = today.substring(0, 4); /* 입력한 오늘일자*/
			    var month = today.substring(4, 6); /* 입력한 오늘일자*/
			    var day = today.substring(6, 8); /* 입력한 오늘일자*/
			    
			    // 연도정보 차이
			    var iCurrentYear = ValueUtil.fixNumber(vsCurrentYear);
			    var iBrthYmd = ValueUtil.fixNumber(year);
			    var age = iCurrentYear - iBrthYmd;
			    
			    // 월정보 차이
			    var iCurrentMonth = ValueUtil.fixNumber(vsCurrentMonth);
			    var iMonth = ValueUtil.fixNumber(month);
			    var m = iCurrentMonth - iMonth;
			    
			    // 일정보차이
			    var iCurrentDay = ValueUtil.fixNumber(vsCurrentDay);
			    var iDay = ValueUtil.fixNumber(day);
			    
			    // 생일지난경우  or 동월달인경우 
			    if (m < 0 || (m === 0 && iCurrentDay < iDay)) {
			        age--;
			    }
			    
			    return age;
			}

			/** 일자범위 기간 차이체크
			 * @param {String} startDate
			 * @param {String} endDate
			 */
			function dataRangeChk_fn(startDate, endDate) {
			    
			    /* 2022-11-02 YOO.CHI.HOON 단위결함 서비스의뢰일자 시작종료일 범위체크로 추가*/
			    if (ValueUtil.isNull(startDate) || ValueUtil.isNull(endDate)) return false;
			    
			    var getStartDateLen = ValueUtil.getLength(startDate);
			    var getEndDateLen = ValueUtil.getLength(endDate);
			    if (getStartDateLen != 8 || getEndDateLen != 8) return false;
			    
			    var iStartDate = ValueUtil.fixNumber(startDate);
			    var iEndDate = ValueUtil.fixNumber(endDate);
			    var boStartDateNum = ValueUtil.isNumber(iStartDate);
			    var boEndDateNum = ValueUtil.isNumber(iEndDate);
			    
			    if (boStartDateNum == false || boEndDateNum == false) return false;
			    
			    var boReturnVal = true;
			    
			    var startDateYear = startDate.substring(0, 4);
			    var startDateMonth = startDate.substring(4, 6);
			    var startDateDay = startDate.substring(6, 8);
			    
			    var endDateYear = endDate.substring(0, 4);
			    var endDateMonth = endDate.substring(4, 6);
			    var endDateDay = endDate.substring(6, 8);
			    
			    // 연도
			    var iStartDateYear = ValueUtil.fixNumber(startDateYear);
			    var iEndDateYear = ValueUtil.fixNumber(endDateYear);
			    var yearStartRange = iStartDateYear - iEndDateYear;
			    var yearEndRange = iEndDateYear - iStartDateYear;
			    // 월
			    var iStartDateMonth = ValueUtil.fixNumber(startDateMonth);
			    var iEndDateMonth = ValueUtil.fixNumber(endDateMonth);
			    var monthStartRange = iStartDateMonth - iEndDateMonth;
			    var monthEndRange = iEndDateMonth - iStartDateMonth;
			    // 일
			    var iStartDateDay = ValueUtil.fixNumber(startDateDay);
			    var iEndDateDay = ValueUtil.fixNumber(endDateDay);
			    var dayStartRange = iStartDateDay - iEndDateDay;
			    var dayEndRange = iEndDateDay - iStartDateDay;
			    
			    var psTitle = "의뢰서비스시작기간";
			    var psMsgId = "서비스시작연도~서비스종료연도 기간 확인 바랍니다.";
			    /* 시작년도, 종료년도 확인*/
			    if (yearStartRange > 0 || yearEndRange < 0) {
			        util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			        boReturnVal = false;
			    }
			    psTitle = "의뢰서비스시작기간";
			    psMsgId = "서비스시작월~서비스종료월 입력월 확인 바랍니다.";
			    
			    if (monthStartRange > 0 || monthEndRange < 0) {
			        util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			        boReturnVal = false;
			    }
			    psTitle = "의뢰서비스시작기간";
			    psMsgId = "서비스시작일~서비스종료일 입력일 확인 바랍니다.";
			    
			    if (dayStartRange > 0 || dayEndRange < 0) {
			        util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			        boReturnVal = false;
			    }
			    return boReturnVal;
			}

