			/** 개인정보 동의여부 만 14세미만 체크
			 * @param {String} trprBirthDate
			 */
			function isChildChk(trprBirthDate) {
			    
			    // 2022-11-24 YOO.CHI.HOON 개인정보 수입˙이용 및 제공동의 변경(여가부 요청)    
			    var today = vsToday /* Today : YYYYMMDD*/
			    var yyyy = vsCurrentYear; /* Year  : YYYY*/
			    var month = vsCurrentMonth < 9 ? "0" + (vsCurrentMonth) : vsCurrentMonth; /* Month : MM*/
			    var day = vsCurrentDay < 10 ? "0" + (vsCurrentDay) : vsCurrentDay; /* Day   : DD*/
			    
			    var ischildVal = ValueUtil.fixNumber((yyyy + month + day)) - ValueUtil.fixNumber(trprBirthDate) - 140000;
			    
			    //    if (ischildVal > 0){
			    //        alert("만 14세미만입니다.");
			    //    }else{
			    //        alert("만 14세이상입니다.");
			    //    }
			    
			    return ischildVal;
			}

			/**
			 * 개인정보동의여부 'Y' 인경우 14세미만 체크 
			 * @param {any} dateString 생년월일 문자열 인수형식(0000-00-00)
			 */
			function isUnder14Chk(dateString){
			    
			    /* 2023-05-09 YOO.CHI.HOON 14세미만 체크 로직 변경 */
			    if(ValueUtil.isNull(dateString)) return;
			    if(dateString.length < 8 || dateString.length > 8) return;
			    
			    /*00000000*/
			    if(dateString.indexOf('-') < 0){
			        if(dateString.length == 8){
			            
			            var yy = dateString.substring(0, 4);
			            var mo = dateString.substring(4, 6);
			            var dd = dateString.substring(6, 8);
			            
			            dateString = yy + '-' + mo + '-' + dd;
			            
			        }
			    }
			    
			    var today     = new Date();
			    var birthDate = new Date(dateString);
			    var age       = today.getFullYear() - birthDate.getFullYear();  /* 나이구하기 2023-2009*/
			    var month     = today.getMonth() - birthDate.getMonth();        /* 현재달 - 생년월일달*/
			    
			    /* 현재달수가 생년월일달수보다 작은경우 , 동일달인경우는 현재일자가 생년월일 일자보다 작은경우((만14세가 도래하지않음))*/
			    if(month < 0 || (month === 0 && today.getDate() < birthDate.getDate())){
			        age--;
			    }
			    
			    return age < 14;
			}

