			    /* 2023-01-25 YOO.CHI.HOON 대상자 등록시 사례진행정보가 예로 나오는데, 디딤/드림은 디폴트로 아니오가 디폴트 세팅*/
			    var newVal = app.lookup("cmb_CASE_TRPR_NOAP_CS_SE_CD").value;
			    
