			         var iLinkMohwCnt = ValueUtil.fixNumber(voDatMap.getValue("LINK_MOHW_CNT"));
			         var iLinkTrprCnt   = ValueUtil.fixNumber(voDatMap.getValue("LINK_TRPR_CNT"));
			         var iTlPhonCnt     = ValueUtil.fixNumber(voDatMap.getValue("TL_PHON_CNT"));         
			         
			         var sDscsnNm = app.lookup("dmRegCntNm").getValue("DSCSN_NM");
			         var sOutrcNm = app.lookup("dmRegCntNm").getValue("OUTRC_NM"); 
			         var sEmrgIntrvnNm = app.lookup("dmRegCntNm").getValue("EMRG_INTRVN_NM"); 
			         var sLinkMohwNm = app.lookup("dmRegCntNm").getValue("LINK_MOHW_NM"); 
			         var sLinkTrprNm    = app.lookup("dmRegCntNm").getValue("LINK_TRPR_NM"); 
