			/**
			 *  사례대상자유형구분코드명, 사례관리구분코드명 return
			 */
			function trprDeleteCondition(){
			    
			    /**
			     * 대상자삭제 기준
			    1. CASE_MNG_SE_CD(사례관리구분코드) : 01(사례대상자미선정),02(사례대상자신청(대기상태))
			    2. CASE_TRPR_TYPE_SE_CD(사례대상자유형구분코드) : 01(직접발굴대상자)
			    ==> 발굴상담, 긴급구조, 1388전화상담, 아웃리치 에 한건 이상 등록시 삭제 불가
			    ==> 복지부연계요청이 한번 이상 있을시 삭제 불가
			     */

			    /** 삭제
			     * 1. 대상자 삭제에 사용여부를 추가해주시고 관련 select 에 일괄 적용 해주세요
			        2. 발굴상담, 긴급구조, 1388전화상담, 아웃리치 에서 한건 이상있을때 
			        ==> "XX에 등록되어 있습니다. 확인 요청드립니다." 로 메세지를 출력해주시기 바랍니다.
			        ==> 관련하여 각 테이블에 사용여부 확인도 해주시기 바랍니다.
			        3. 복지부 연계된건은 삭제 불가입니다.
			     */
			    var sCaseMngSeCd      = app.lookup("dmDetail").getValue("CASE_MNG_SE_CD");
			    var sCaseTrprTypeSeCd = app.lookup("dmDetail").getValue("CASE_TRPR_TYPE_SE_CD");
			    var retMap = {};
			    
			    var voDatSet1 = app.lookup("dsCaseMngSeCd");
			    var voDatSet2 = app.lookup("dsCaseTrprTypeSeCd");
			    
			    var sCaseMngSeNm      = '';
			    for (var idx=0; idx< voDatSet1.getRowCount(); idx++){
			        
			        if(sCaseMngSeCd == voDatSet1.getValue(idx, "CMMNS_CD_VALUE")){
			            sCaseMngSeNm = voDatSet1.getValue(idx, "CMMNS_CD_VALUE_NM");
			            break;
			        }
			    }
			    var sCaseTrprTypeSeNm = '';
			    for (var idx=0; idx< voDatSet2.getRowCount(); idx++){
			        
			        if(sCaseTrprTypeSeCd == voDatSet2.getValue(idx, "CMMNS_CD_VALUE")){
			            sCaseTrprTypeSeNm = voDatSet2.getValue(idx, "CMMNS_CD_VALUE_NM");
			            break;
			        }
			    }
			    
			     retMap = {"CASE_TRPR_TYPE_SE_NM" : sCaseTrprTypeSeNm,
			               "CASE_TRPR_TYPE_SE_CD" : sCaseTrprTypeSeCd,
			               "CASE_MNG_SE_NM"       : sCaseMngSeNm,
			               "CASE_MNG_SE_CD"       : sCaseMngSeCd
			              };    

			    return retMap;
			}

