			/** 서비스제공동의여부
			 * @param {any} psVal
			 */
			function prvcPvsnAgreYnChk(puValue){
			    
			    if(ValueUtil.isNull(puValue)) return false;
			    
			    var vcRdb = app.lookup("rdb_PRVC_PVSN_AGR_ASETT_SE_CD");
			    var vcDti = app.lookup("dti_PRVC_AGRE_YMD");
			    if ("Y" == puValue) {
			        
			        app.lookup("opt_PRTCR_AGRE_YN").style.removeClass("label");
			        app.lookup("opt_PRTCR_AGRE_YN").style.addClass("label require");
			        app.lookup("opt_PRVC_PVSN_AGRE_YMD").style.removeClass("label");
			        app.lookup("opt_PRVC_PVSN_AGRE_YMD").style.addClass("label require");
			        
			        vcRdb.enabled = true;
			        vcDti.enabled = true;
			        
			    } else {
			        
			        app.lookup("opt_PRTCR_AGRE_YN").style.removeClass("label require");
			        app.lookup("opt_PRTCR_AGRE_YN").style.addClass("label");
			        app.lookup("opt_PRVC_PVSN_AGRE_YMD").style.removeClass("label require");
			        app.lookup("opt_PRVC_PVSN_AGRE_YMD").style.addClass("label");
			        
			        vcDti.value = null;
			        vcRdb.value = null;
			        
			        vcRdb.enabled = false;
			        vcDti.enabled = false;
			    }
			    
			    app.lookup("grp16").redraw();    
			}

			/*
			 * "미확인" 버튼(btnUncnfr)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnUncnfrClick(e) {
			    var btnUncnfr = e.control;
			    
			    // 2022-12-02 YOO.CHI.HOON
			    /*
			     * 대상자등록화면관련하여 추가 요건사항을 정리해서 드립니다.
			    1. 대상자명입력 옆에 "미확인"버튼 추가
			    ==> 해당 버튼은 입력상태일때만 표시
			    ==> 단위업무구분코드중 주민번호필수가 아닌 단위업무만 표시
			    2. "미확인" 버튼 클릭시
			    ==> 대상자명 : "미확인", disable 처리
			    ==> 생년월일 : "19000101", disable 처리
			    ==> 성별 : "미확인", disable 처리
			    3. 저장시(insert) - 개인식별번호부여시
			    ==> 대상자명이 미확인이고 생년월일이 19000101 시 식별번호로직 skip
			    ==> 성별은 추후 바뀔수도 있을것 같으니 두가지만 조건으로 걸어주세요
			     */
			    
			    var voDataMap   = app.lookup("dmDetail");
			    var vcGrdFomLot = app.lookup("grpTRPR_NM").getLayout();
			    var vcGrdTrpr   = app.lookup("cmnBirthDay");
			    var vcRdbSxdc   = app.lookup("rdb_SXDC_SE_CD");
			    var vcIpbTrprNm = app.lookup("ipb_TRPR_NM");
			    var vcBtn       = app.lookup("btnUncnfr");
			    
			    var vcCombo1 = app.lookup("cmb_FAM_SHAPE_SE_CD");
			    var vcCombo2 = app.lookup("cmb_RESIDE_SHAPE_SE_CD");
			    var vcCombo3 = app.lookup("cmb_PBLAST_SE_CD");      
			    
			    /* 2023-01-16 미확인시 주민번호, 개인식별 null*/
			    var vcRrno       = app.lookup("mse_RRNO");
			    var vcIndvIdntfc = app.lookup("dti_INDV_IDNTFC_CRTR_YMD");
			    
			    if (chgCnt == 0) {
			        
			        vcBtn.value = "미확인취소";
			        
			        /* 값셋팅*/
			        voDataMap.setValue("TRPR_NM", "미확인");
			        voDataMap.setValue("TRPR_BRTH_YMD", "19000101");
			        voDataMap.setValue("SXDC_SE_CD", "X");
			        
			        voDataMap.setValue("RRNO", "");
			        voDataMap.setValue("INDV_IDNTFC_CRTR_YMD", "");
			        
			        /* vible 처리*/
			        vcIpbTrprNm.enabled = false;
			        vcRdbSxdc.enabled = false;
			        vcGrdTrpr.enabled = false;
			        vcRrno.enabled = false;
			        vcIndvIdntfc.enabled = false;
			        
			        vcCombo1.selectItem(8);
			        vcCombo2.selectItem(6);
			        vcCombo3.selectItem(4);        
			        
			//        comboBoxSelect(1);  
			        
			        /* 버튼전환여부*/
			        chgCnt++;
			    } else if (chgCnt > 0) {
			        
			        vcBtn.value = "미확인"
			        
			        /* 값셋팅*/
			        voDataMap.setValue("TRPR_NM", null);
			        voDataMap.setValue("TRPR_BRTH_YMD", null);
			        voDataMap.setValue("SXDC_SE_CD", null);
			        voDataMap.setValue("TRPR_AGE", null);
			        
			        voDataMap.setValue("RRNO", null);
			        voDataMap.setValue("INDV_IDNTFC_CRTR_YMD", null);        
			        
			        /* vible 처리*/
			        vcIpbTrprNm.enabled = true;
			        vcRdbSxdc.enabled = true;
			        vcGrdTrpr.enabled = true;
			        vcRrno.enabled = true;
			        vcIndvIdntfc.enabled = true;       
			        
			        vcCombo1.clearSelection(); 
			        vcCombo2.clearSelection(); 
			        vcCombo3.clearSelection();         
			        
			//        comboBoxSelect(2);   
			        
			        /* 버튼전환여부*/
			        chgCnt = 0;
			    }
			    
			    /* 새로고침*/
			    app.lookup("grpTrprInfo").redraw();
			}


			/** 대상자 미확인시 사용자편의 미확인 선택
			 * @param {any} cmbVal
			 */
			function comboBoxSelect (cmbVal){
			    
			    
			    if(ValueUtil.isNull(cmbVal)) return;
			    
			    var rowData = {"CMMNS_CD_VALUE_NM" : "미확인",   
			                   "CMMNS_CD_VALUE"    : null
			                };
			    
			        /* 2023-01-19 YOO.CHI.HOON 미확인수정(여가부승인)*/
			        /*
			        1. 대상자 미확인 클릭시 가족구성형태, 주거형태, 사회보장 구분이 미확인으로 나오도록 
			            ==> 해당건은 관련하여 적용하면 되는지요
			            =>박정식 답변 : 네. 그렇게 하시면 되는데요. 처음에 선택할때 그렇게 선택하되 수정이 가능해야합니다. 
			            대상자 미확인 경우에도 대부문 필수값이 미확인이 되므로 입력시 편의기능을 해달라고 한 것입니다.
			        */ 
			    
			    if(cmbVal == 1 || cmbVal == '1'){
			        
			        var voDataSet1 = app.lookup("dsFamShape");  // dsFamShape 가족구성형태
			        var voDataSet2 = app.lookup("dsResideShape"); // dsResideShape 주거형태
			        var voDataSet3 = app.lookup("dsPblastSeCd"); // dsPblastSeCd 사회보장구분
			        
			        voDataSet1.insertRowData(0, false, rowData);
			        voDataSet2.insertRowData(0, false, rowData);
			        voDataSet3.insertRowData(0, false, rowData);
			        
			        var vcCombo1 = app.lookup("cmb_FAM_SHAPE_SE_CD");
			        var vcCombo2 = app.lookup("cmb_RESIDE_SHAPE_SE_CD");
			        var vcCombo3 = app.lookup("cmb_PBLAST_SE_CD");   
			        
			        vcCombo1.selectItem(0);
			        vcCombo2.selectItem(0);
			        vcCombo3.selectItem(0);        
			        
			    }else if(cmbVal == 2 || cmbVal == '2'){
			        
			        var voDataSet1 = app.lookup("dsFamShape");  // dsFamShape 가족구성형태
			        var voDataSet2 = app.lookup("dsResideShape"); // dsResideShape 주거형태
			        var voDataSet3 = app.lookup("dsPblastSeCd"); // dsPblastSeCd 사회보장구분
			        
			        voDataSet1.deleteRow(0);
			        voDataSet2.deleteRow(0);
			        voDataSet3.deleteRow(0);
			        
			        var vcCombo1 = app.lookup("cmb_FAM_SHAPE_SE_CD");
			        var vcCombo2 = app.lookup("cmb_RESIDE_SHAPE_SE_CD");
			        var vcCombo3 = app.lookup("cmb_PBLAST_SE_CD");   
			        
			    }
			}

